eNoKey: "🔑 SAUCE_KEY belum diset — register gratis di saucenao.com (account page → API key), taruh di .saucekey, kasih tau aku.", sauceWait: "🔎 nyari saucenya…", sauceNone: "🤷 gak dapet match dari SauceNAO — coba gambar yang lebih jelas / di-crop, atau cari manual via Google Lens.", sauceFail: "⚠️ SauceNAO gak bisa dihubungi (timeout/egress) — coba lagi ntar.", sauceErr: (m) => "⚠️ SauceNAO nolak: " + m, sauceHead: (n) => "🔎 <b>SAUCE</b> — " + n + " match:", sauceLensBtn: "🌐 Google Lens",
