export async function uiLang(env) {
  return (await env.KV.get(UI_LANG_KEY)) === "id" ? UI.id : UI.en;
}

export function fmtTok(n) {
  n = n || 0;
  return n >= 1000 ? (n >= 100000 ? String(Math.round(n / 1000)) : (n / 1000).toFixed(1)) + "k" : String(n);
}

export function fmtWIB(sec, L) {
  const d = new Date((sec + WIB) * 1000);
  const pad = n => String(n).padStart(2, "0");
  const days = (L && L.fmtDays) || UI.en.fmtDays;
  return days[d.getUTCDay()] + " " + pad(d.getUTCDate()) + "/" + pad(d.getUTCMonth() + 1) + " " + pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes()) + " WIB";
}

export function nowWIB() {
  const d = new Date((Math.floor(Date.now() / 1000) + WIB) * 1000);
  const pad = n => String(n).padStart(2, "0");
  const days = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
  const mon = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
  return days[d.getUTCDay()] + ", " + pad(d.getUTCDate()) + " " + mon[d.getUTCMonth()] + " " + d.getUTCFullYear() + " " + pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes()) + " WIB";
}
